/// <summary>
/// Controller class for the Sales order bundling report
/// </summary>
class METSalesOrderShipmentBundlingReportController extends SrsReportRunController
{
    METOrderShipmentBundlingReportContract contract;
    METOrderShipmentBundlingReportHeaderTmp     bundlingReportHeaderTmp;

}

Method.Source:
/// <summary>
/// Handles the logic of priniting the report
/// </summary>
/// <param name = "_args">controller args</param>
static void main(Args _args)
{
    METSalesOrderShipmentBundlingReportController controller;

    controller = new METSalesOrderShipmentBundlingReportController();
    controller.parmArgs(_args);

    if (_args.menuItemName() == menuItemActionStr(METTransferOrderShipmentBundlingReportController))
    {
        controller.parmReportName(ssrsReportStr(METTransferOrderShipmentBundlingReport, Report));
        controller.parmDialogCaption("@MET:TOBundleReport");
    }
    else
    {
        controller.parmReportName(ssrsReportStr(METSalesOrderShipmentBundlingReport, NewReport));
        controller.parmDialogCaption("@MET:SOBundleReport");
    }

    METOrderShipmentBundlingReportContract contract = controller.parmReportContract().parmRdpContract();

    controller.startOperation();
}

protected METOrderShipmentBundlingReportContract parmContract()
{
    if (!contract)
    {
        contract = this.parmReportContract().parmRdpContract() as METOrderShipmentBundlingReportContract;
    }
    return contract;
}

/// <summary>
///
/// </summary>
protected void preRunModifyContract()
{
    METOrderTransactionType     transactionType;
    METSalesOrderShipmentLoadHeader             shipmentLoadHeader;
    MetLoadId   loadId = this.parmContract().parmLoadId();

    while select shipmentLoadHeader
            where shipmentLoadHeader.LoadId == loadId
    {
        if (shipmentLoadHeader.LoadStatus != MetLoadStatus::Shipped)
        {
            throw Error(strFmt("@MET:LoadNotShipped", loadId));
        }
        bundlingReportHeaderTmp.LoadID = shipmentLoadHeader.LoadId;
        bundlingReportHeaderTmp.ShipmentID = shipmentLoadHeader.ShipmentId;
        bundlingReportHeaderTmp.Route = shipmentLoadHeader.Route;
        bundlingReportHeaderTmp.RouteStopNum = shipmentLoadHeader.RouteStopNum;
        bundlingReportHeaderTmp.insert();

        transactionType = shipmentLoadHeader.TransactionType;
    }



    while select bundlingReportHeaderTmp
        order by Route, RouteStopNum asc
    {
        this.parmContract().parmLoadId(bundlingReportHeaderTmp.LoadID);
        this.parmContract().parmShipmentId(bundlingReportHeaderTmp.ShipmentID);

        super();
    }
}
